<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import PageShell from '../PageShell.vue'
import {api,type User} from '../api'
import {usePage} from '../page'
import {yuan,cycleName,dateText} from '../commerce'
type Filters={order_no:string;email:string;user_id:string;kind:string;status:string;time_field:string;gateway_trade_no:string;from:string;to:string}
type Order={id:number;order_no:string;user_id:number;username:string;kind:string;plan_name:string;cycle:string;amount_cents:number;status:string;payment_method_name:string;gateway_trade_no:string;created_at:string;paid_at:string|null;actor_name?:string;snapshot?:{note?:string;expires_at?:string|null;next_reset_at?:string|null;rate?:string;mode?:string;source_order_id?:number}}
const params=new URLSearchParams(location.search)
const blank=():Filters=>({order_no:'',email:'',user_id:'',kind:'',status:'',time_field:'created',gateway_trade_no:'',from:'',to:''})
const initial=blank();for(const key of Object.keys(initial) as (keyof Filters)[])initial[key]=params.get(key)||initial[key]
const applied=ref<Filters>({...initial}),draft=reactive<Filters>({...initial}),dates=ref<[Date,Date]|null>(initial.from&&initial.to?[new Date(initial.from),new Date(initial.to)]:null)
const filtersOpen=ref(false),orders=ref<Order[]>([]),total=ref(0),page=ref(1),detail=ref<Order|null>(null),detailOpen=ref(false),fetchingDetail=ref(false),target=ref<User|null>(null)
const kinds:Record<string,string>={purchase:'套餐购买',renewal:'套餐续费',recharge:'余额充值',rebate:'邀请返利'},statuses:Record<string,string>={paid:'已完成',pending:'待支付',cancelled:'已取消'}
function searchParams(){const query=new URLSearchParams();for(const [key,value]of Object.entries(applied.value))if(value&&(key!=='time_field'||value!=='created'))query.set(key,value);return query}
function updateURL(){const query=searchParams();history.replaceState(null,'','/admin/orders'+(query.size?'?'+query.toString():''))}
const {me,loading,error,busy,run,refresh}=usePage(async()=>{const query=searchParams();query.set('page',String(page.value));const data=await api<{items:Order[];total:number}>('admin/orders?'+query);orders.value=data.items;total.value=data.total;const id=applied.value.user_id;if(id){if(String(target.value?.id)!==id){const users=await api<User[]>('admin/users/'+encodeURIComponent(id));target.value=users[0]||null}}else target.value=null},{admin:true})
const filtering=computed(()=>Object.entries(applied.value).some(([key,value])=>value&&!(key==='time_field'&&value==='created')))
function openFilters(){Object.assign(draft,applied.value);dates.value=draft.from&&draft.to?[new Date(draft.from),new Date(draft.to)]:null;filtersOpen.value=true}
async function apply(){if(dates.value&&dates.value.some(v=>!Number.isFinite(v.getTime()))){ElMessage.error('时间范围无效');return};draft.from=dates.value?.[0].toISOString()||'';draft.to=dates.value?.[1].toISOString()||'';applied.value={...draft};page.value=1;updateURL();filtersOpen.value=false;await refresh()}
async function reset(){applied.value=blank();Object.assign(draft,blank());dates.value=null;page.value=1;updateURL();await refresh()}
async function clearUser(){applied.value={...applied.value,user_id:''};target.value=null;page.value=1;updateURL();await refresh()}
async function show(order:Order){if(fetchingDetail.value)return;fetchingDetail.value=true;await run(async()=>{detail.value=await api<Order>('admin/orders/'+order.id);detailOpen.value=true});fetchingDetail.value=false}
function content(order:Order){if(order.kind==='recharge')return order.payment_method_name||'管理员充值';if(order.kind==='rebate')return order.plan_name+' · 邀请返利';return order.plan_name+' · '+cycleName(order.cycle)}
</script>
<template><PageShell :me="me" :loading="loading" :error="error" active="orders" admin><section class="surface"><div class="section-header"><strong>订单查询</strong><div><el-button :type="filtering?'primary':'default'" @click="openFilters">筛选</el-button><el-button v-if="filtering" @click="reset">清除筛选</el-button><el-button @click="refresh">刷新</el-button></div></div><div class="section-body"><p v-if="applied.user_id" class="order-user-scope">当前用户：{{target?.username||'#'+applied.user_id}} <el-button link type="primary" @click="clearUser">取消用户筛选</el-button></p><el-table :data="orders" empty-text="没有符合条件的订单"><el-table-column label="订单号" min-width="235"><template #default="{row}"><el-button link type="primary" :disabled="fetchingDetail" @click="show(row)">{{row.order_no}}</el-button></template></el-table-column><el-table-column prop="username" label="用户邮箱 / 用户名" min-width="200"/><el-table-column label="类型" width="110"><template #default="{row}">{{kinds[row.kind]||row.kind}}</template></el-table-column><el-table-column label="内容" min-width="190"><template #default="{row}">{{content(row)}}</template></el-table-column><el-table-column label="金额 / 元" width="110"><template #default="{row}">{{row.kind==='rebate'?'+':''}}{{yuan(row.amount_cents)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='paid'?'success':'info'">{{statuses[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="180"><template #default="{row}">{{dateText(row.created_at)}}</template></el-table-column><el-table-column label="完成时间" min-width="180"><template #default="{row}">{{dateText(row.paid_at,'尚未完成')}}</template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="refresh" class="user-pagination"/></div></section><el-dialog v-model="filtersOpen" title="筛选订单" width="680px" class="managed-form-dialog"><el-form label-position="top" @submit.prevent="apply"><div class="form-grid"><el-form-item label="订单号"><el-input v-model="draft.order_no" maxlength="128" placeholder="支持部分订单号"/></el-form-item><el-form-item label="用户邮箱 / 用户名"><el-input v-model="draft.email" maxlength="254" placeholder="支持部分邮箱或用户名"/></el-form-item><el-form-item label="用户 ID"><el-input v-model="draft.user_id" inputmode="numeric" placeholder="留空查询全部用户"/></el-form-item><el-form-item label="支付平台流水号"><el-input v-model="draft.gateway_trade_no" maxlength="256"/></el-form-item><el-form-item label="订单类型"><el-select v-model="draft.kind"><el-option label="全部" value=""/><el-option v-for="(name,value) in kinds" :key="value" :label="name" :value="value"/></el-select></el-form-item><el-form-item label="订单状态"><el-select v-model="draft.status"><el-option label="全部" value=""/><el-option v-for="(name,value) in statuses" :key="value" :label="name" :value="value"/></el-select></el-form-item></div><el-form-item label="时间依据"><el-select v-model="draft.time_field"><el-option label="创建时间" value="created"/><el-option label="完成时间" value="paid"/></el-select></el-form-item><el-form-item label="时间范围"><el-date-picker v-model="dates" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item></el-form><template #footer><el-button @click="filtersOpen=false">取消</el-button><el-button type="primary" @click="apply">查询</el-button></template></el-dialog><el-dialog v-model="detailOpen" title="订单详情" width="640px" class="managed-form-dialog"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="订单号">{{detail.order_no}}</el-descriptions-item><el-descriptions-item label="用户">{{detail.username}}（#{{detail.user_id}}）</el-descriptions-item><el-descriptions-item label="类型">{{kinds[detail.kind]}}</el-descriptions-item><el-descriptions-item label="内容">{{content(detail)}}</el-descriptions-item><el-descriptions-item label="金额">{{detail.kind==='rebate'?'+':''}}{{yuan(detail.amount_cents)}} 元</el-descriptions-item><el-descriptions-item label="状态">{{statuses[detail.status]}}</el-descriptions-item><el-descriptions-item label="创建时间">{{dateText(detail.created_at)}}</el-descriptions-item><el-descriptions-item label="完成时间">{{dateText(detail.paid_at,'尚未完成')}}</el-descriptions-item><el-descriptions-item v-if="detail.gateway_trade_no" label="支付流水号">{{detail.gateway_trade_no}}</el-descriptions-item><el-descriptions-item v-if="detail.actor_name" label="操作管理员">{{detail.actor_name}}</el-descriptions-item><el-descriptions-item v-if="detail.snapshot?.note" label="备注">{{detail.snapshot.note}}</el-descriptions-item><template v-if="detail.kind==='purchase'||detail.kind==='renewal'"><el-descriptions-item label="购买时预计到期">{{dateText(detail.snapshot?.expires_at)}}</el-descriptions-item><el-descriptions-item label="购买时下次重置">{{dateText(detail.snapshot?.next_reset_at,'无自动重置')}}</el-descriptions-item></template><el-descriptions-item v-if="detail.kind==='rebate'&&detail.snapshot?.rate" label="返利比例">{{detail.snapshot.rate}}%</el-descriptions-item></el-descriptions></el-dialog></PageShell></template>
<style scoped>.order-user-scope{margin:0 0 20px;overflow-wrap:anywhere}</style>
